use std::collections::HashMap;
use std::sync::{Arc, RwLock, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};
use std::thread;

/// A serialization registry that processes untrusted user uploads.
/// Each upload is deserialized and registered with a priority queue
/// for batch processing.

#[derive(Clone, Debug)]
pub struct SerializedPayload {
    pub user_id: u64,
    pub data: Vec<u8>,
    pub priority: u32,
    pub timestamp: u64,
}

#[derive(Clone, Debug)]
pub struct ProcessingTicket {
    pub ticket_id: u64,
    pub position: usize,
    pub committed_at: u64,
}

pub struct ProcessingQueue {
    queue: Vec<(u32, SerializedPayload)>,
    tickets: HashMap<u64, ProcessingTicket>,
    next_ticket: u64,
}

impl ProcessingQueue {
    pub fn new() -> Self {
        Self {
            queue: Vec::new(),
            tickets: HashMap::new(),
            next_ticket: 1,
        }
    }

    pub fn insert(&mut self, payload: SerializedPayload) -> ProcessingTicket {
        let position = self.find_insert_position(payload.priority);
        self.queue.insert(position, (payload.priority, payload.clone()));
        let ticket = ProcessingTicket {
            ticket_id: self.next_ticket,
            position,
            committed_at: current_timestamp(),
        };
        self.next_ticket += 1;
        self.tickets.insert(ticket.ticket_id, ticket.clone());
        ticket
    }

    fn find_insert_position(&self, priority: u32) -> usize {
        // Higher priority = earlier position (lower index)
        for (i, (p, _)) in self.queue.iter().enumerate() {
            if priority > *p {
                return i;
            }
        }
        self.queue.len()
    }

    pub fn drain_batch(&mut self, count: usize) -> Vec<SerializedPayload> {
        let n = count.min(self.queue.len());
        self.queue.drain(0..n).map(|(_, p)| p).collect()
    }
}

pub struct UploadProcessor {
    queue: Arc<RwLock<ProcessingQueue>>,
    pending_validations: Arc<Mutex<HashMap<u64, SerializedPayload>>>,
}

impl UploadProcessor {
    pub fn new() -> Self {
        Self {
            queue: Arc::new(RwLock::new(ProcessingQueue::new())),
            pending_validations: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Phase 1: Accept and validate the upload format
    pub fn submit_upload(&self, raw_data: &[u8], user_id: u64) -> Result<u64, String> {
        let payload = self.deserialize_payload(raw_data, user_id)?;
        let validation_id = current_timestamp() ^ (user_id << 16);

        // Store in pending while we validate
        let mut pending = self.pending_validations.lock().unwrap();
        pending.insert(validation_id, payload);
        Ok(validation_id)
    }

    /// Phase 2: Commit validated upload to the processing queue
    /// The priority is read from the pending payload at commit time
    pub fn commit_upload(&self, validation_id: u64) -> Result<ProcessingTicket, String> {
        let payload = {
            let mut pending = self.pending_validations.lock().unwrap();
            pending.remove(&validation_id)
                .ok_or_else(|| "Validation ID not found".to_string())?
        };

        // VULNERABILITY: Between releasing pending_validations lock and acquiring
        // queue write lock, another thread can observe the queue state and
        // front-run by inserting a higher-priority item.
        // The RwLock allows concurrent readers to see queue state.

        let mut queue = self.queue.write().unwrap();
        let ticket = queue.insert(payload);
        Ok(ticket)
    }

    /// Allows observing current queue state (used by monitoring/protocol)
    pub fn peek_queue_depth(&self) -> usize {
        let queue = self.queue.read().unwrap();
        queue.queue.len()
    }

    /// Allows observing the current highest priority in queue
    pub fn peek_top_priority(&self) -> Option<u32> {
        let queue = self.queue.read().unwrap();
        queue.queue.first().map(|(p, _)| *p)
    }

    fn deserialize_payload(&self, raw_data: &[u8], user_id: u64) -> Result<SerializedPayload, String> {
        if raw_data.len() < 8 {
            return Err("Payload too short".to_string());
        }

        let priority = u32::from_le_bytes(
            raw_data[0..4].try_into().map_err(|_| "Invalid priority bytes".to_string())?
        );
        let data_len = u32::from_le_bytes(
            raw_data[4..8].try_into().map_err(|_| "Invalid length bytes".to_string())?
        ) as usize;

        if raw_data.len() < 8 + data_len {
            return Err("Payload data truncated".to_string());
        }

        // Cap priority to prevent abuse
        let capped_priority = priority.min(1000);

        Ok(SerializedPayload {
            user_id,
            data: raw_data[8..8+data_len].to_vec(),
            priority: capped_priority,
            timestamp: current_timestamp(),
        })
    }
}

/// Front-running attack: observer thread watches queue state between
/// victim's validation and commit, then inserts higher-priority payload
pub fn demonstrate_frontrun(processor: &UploadProcessor) {
    // Attacker monitors queue depth changes
    let initial_depth = processor.peek_queue_depth();
    let current_top = processor.peek_top_priority().unwrap_or(0);

    // Attacker crafts payload with priority just above current top
    let attack_priority = (current_top + 1).min(1000);
    let mut attack_data = Vec::new();
    attack_data.extend_from_slice(&attack_priority.to_le_bytes());
    attack_data.extend_from_slice(&4u32.to_le_bytes());
    attack_data.extend_from_slice(b"ATCK");

    let vid = processor.submit_upload(&attack_data, 9999).unwrap();
    let _ = processor.commit_upload(vid);
}

fn current_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_ordering() {
        let proc = UploadProcessor::new();

        let mut data1 = Vec::new();
        data1.extend_from_slice(&100u32.to_le_bytes());
        data1.extend_from_slice(&4u32.to_le_bytes());
        data1.extend_from_slice(b"usr1");

        let vid1 = proc.submit_upload(&data1, 1).unwrap();
        let t1 = proc.commit_upload(vid1).unwrap();
        assert_eq!(t1.position, 0);
    }

    #[test]
    fn test_frontrun_possible() {
        let proc = Arc::new(UploadProcessor::new());

        // Victim submits
        let mut victim_data = Vec::new();
        victim_data.extend_from_slice(&500u32.to_le_bytes());
        victim_data.extend_from_slice(&4u32.to_le_bytes());
        victim_data.extend_from_slice(b"VCTM");

        let vid = proc.submit_upload(&victim_data, 1).unwrap();

        // Attacker observes and front-runs before victim commits
        let proc2 = proc.clone();
        let attacker = thread::spawn(move || {
            demonstrate_frontrun(&proc2);
        });
        attacker.join().unwrap();

        // Victim commits after attacker
        let ticket = proc.commit_upload(vid).unwrap();
        // Victim ends up behind attacker
        assert!(ticket.position > 0);
    }
}
